"""Population metadata/traversals and purposive cross-specialty witnesses, exact SQL registry."""
import sys
from common import *
def main():
 c=connect();c.execute('ATTACH ? AS base (READ_ONLY)',[str(C/'independent_audit/audit.duckdb')]);r=Registry(c,'analysis');prep=[]
 if "--resume" in sys.argv:
  r.results=json.loads((R/"analysis.json").read_text());r.queries=json.loads((R/"analysis_queries.json").read_text());original_run=r.run
  def resumed(name,sql,denominator,params=None):
   if name in r.results:return r.results[name]
   return original_run(name,sql,denominator,params)
  r.run=resumed
 def create(sql,params=None):c.execute(sql,params or []);prep.append(dict(sql=sql,parameters=params or []));dump(R/'analysis_preparation_queries.json',prep)
 r.run('totals',"SELECT 'nodes' family,count(*) records,count(DISTINCT id) distinct_ids FROM nodes UNION ALL SELECT 'edges',count(*),count(DISTINCT id) FROM e",'Complete snapshot, independently counted from manifest-verified input rows.')
 r.run('labels','SELECT label,count(*) records FROM nodes GROUP BY 1 ORDER BY 1','Complete node families.')
 r.run('relationships','SELECT type,predicate,count(*) records FROM e GROUP BY 1,2 ORDER BY 1,2','Complete relationship distribution; native/Biolink types observed, not assumed.')
 r.run('directions',"SELECT type,split_part(subject,':',1) subject_prefix,split_part(object,':',1) object_prefix,count(*) edges FROM e GROUP BY 1,2,3 ORDER BY 1,2,3",'Actual subject/object prefixes for every edge; README is interpretation guidance, not proof.')
 r.run('endpoint_integrity',"SELECT count(*) edges,count(*) FILTER(WHERE s.id IS NULL) missing_subject,count(*) FILTER(WHERE o.id IS NULL) missing_object FROM e LEFT JOIN nodes s ON s.id=e.subject LEFT JOIN nodes o ON o.id=e.object",'Every released relationship; no missing endpoint is silently dropped.')
 r.run('role_consistency',"SELECT type,coalesce(publication_role,reference_type) role,source_system,count(*) edges,count(DISTINCT (subject,object)) pairs,count(*) FILTER(WHERE array_length(also_asserted_by_source_system)>0) multi_source_edges FROM e WHERE type IN ('VALIDATED_BY','CITES_BACKGROUND','HAS_DERIVED_PUBLICATION') GROUP BY 1,2,3 ORDER BY 1,2,3",'Complete native trial-publication population by observed source role; repeated source provenance is not independent clinical validation.')
 r.run('source_registry',"SELECT count(*) edges,count(*) FILTER(WHERE provenance_id IS NOT NULL AND provenance_id<>'') provenance_id,count(*) FILTER(WHERE primary_knowledge_source IS NOT NULL AND primary_knowledge_source<>'') primary_source,count(*) FILTER(WHERE knowledge_level IS NOT NULL) knowledge_level,count(*) FILTER(WHERE agent_type IS NOT NULL) agent_type FROM e",'Complete edges; primary knowledge source is distinct from a release-linked provenance ID.')
 r.run('citation_denominators',"SELECT p.population,(SELECT count(*) FROM article a WHERE NOT p.exclude_stubs OR NOT a.stub) articles,count(*) citation_edge_rows,count(*) FILTER(WHERE cc.subject=cc.object) self_link_rows,count(DISTINCT (cc.subject,cc.object)) FILTER(WHERE cc.subject<>cc.object) distinct_nonself_citing_pairs,count(DISTINCT cc.object) articles_cited_in_corpus FROM base.c cc JOIN article a ON a.id=cc.subject JOIN article b ON b.id=cc.object CROSS JOIN populations p WHERE NOT p.exclude_stubs OR (NOT a.stub AND NOT b.stub) GROUP BY p.population,p.exclude_stubs",'In-corpus citation population with both endpoints eligible; self-links excluded from ranking counts.')
 r.run('community_variation',"SELECT p.population,count(DISTINCT x.community_id) community_ids,count(DISTINCT x.community_id_coarse) coarse_ids,count(DISTINCT x.community_id_mesh) mesh_ids,count(DISTINCT x.pagerank_score) pagerank_values FROM article a JOIN analytics x ON x.id=a.id CROSS JOIN populations p WHERE NOT p.exclude_stubs OR NOT a.stub GROUP BY 1",'All observed analytic values; zero/sentinel states are separately reported.')
 r.run('major_coverage',"SELECT p.population,m.edge_major,count(*) edges FROM am m JOIN article a ON a.id=m.article CROSS JOIN populations p WHERE NOT p.exclude_stubs OR NOT a.stub GROUP BY 1,2 ORDER BY 1,2",'Article HAS_MESH flags with/without identity-only stubs; true is required for ranking.')
 r.run('major_disagreements',"SELECT p.population,count(*) comparable_edges,count(*) FILTER(WHERE edge_major<>node_label_major) disagreements FROM am m JOIN article a ON a.id=m.article CROSS JOIN populations p WHERE (NOT p.exclude_stubs OR NOT a.stub) AND edge_major IS NOT NULL AND node_label_major IS NOT NULL GROUP BY 1",'Both edge flag and Article major-label list observed; preferred-name comparison only.')
 r.run('check_tags','SELECT * FROM stop ORDER BY name','Same declared 40-name NLM reference list as v0.1; resolved to frozen v0.2 node IDs.')
 r.run('trial_mesh_semantics','SELECT study_aspect,mesh_type,count(*) edges FROM trial_qualified GROUP BY 1,2 ORDER BY 1,2','All trial HAS_MESH; condition mesh-list alone is used for same-condition paths.')
 r.run('stub_edges',"SELECT e.type,count(*) edges,count(*) FILTER(WHERE s.stub) stub_subject,count(*) FILTER(WHERE o.stub) stub_object FROM e LEFT JOIN article s ON s.id=e.subject LEFT JOIN article o ON o.id=e.object WHERE s.stub OR o.stub GROUP BY 1 ORDER BY 1",'Every relationship incident to identity-only Articles; determines whether traversal/ranking invariance can be asserted.')
 r.run('entrypoints',"SELECT p.population,count(*) articles,count(*) FILTER(WHERE coalesce(a.doi,'')<>'') doi,count(*) FILTER(WHERE coalesce(a.pmcid,'')<>'') pmcid,count(*) FILTER(WHERE coalesce(a.name,'')<>'') title,count(*) FILTER(WHERE coalesce(a.journal,'')<>'') journal,count(*) FILTER(WHERE array_length(a.pub_types)>0) publication_types,count(*) FILTER(WHERE array_length(a.mesh_major_topics)>0) major_topic_list FROM article a CROSS JOIN populations p WHERE NOT p.exclude_stubs OR NOT a.stub GROUP BY 1",'All Article denominators, with/without canonical stub marker. Empty/null values are not counted as metadata.')
 r.run('other_entrypoints',"SELECT label,count(*) nodes,count(*) FILTER(WHERE coalesce(name,'')<>'') title,count(*) FILTER(WHERE coalesce(iri,url,'')<>'') direct_url,count(*) FILTER(WHERE coalesce(openalex_author_id,'')<>'') openalex_author_id,count(*) FILTER(WHERE coalesce(orcid,'')<>'') orcid,count(*) FILTER(WHERE coalesce(profile_orcid,'')<>'') profile_orcid,count(*) FILTER(WHERE coalesce(nct_id,'')<>'') nct_id FROM nodes WHERE label IN ('Author','ClinicalTrial','MedlinePlus','Journal','PMCRecord') GROUP BY 1 ORDER BY 1",'All named node families; presence of a CURIE does not manufacture a missing property.')
 r.run('publication_types',"SELECT p.population,t.type,count(DISTINCT a.id) articles FROM article a CROSS JOIN populations p CROSS JOIN unnest(a.pub_types) t(type) WHERE NOT p.exclude_stubs OR NOT a.stub GROUP BY 1,2 ORDER BY 1,2",'Complete exact nonexclusive publication type labels, no title-derived designs.')
 for field,size in [('community_id','community_size'),('community_id_coarse','community_size_coarse'),('community_id_mesh','community_size_mesh')]:
  r.run(field+'_consistency',f"SELECT population,count(*) nonnegative_groups,count(*) FILTER(WHERE sizes>1) groups_with_conflicting_sizes,count(*) FILTER(WHERE stored_size<observed) groups_with_stored_size_less_than_observed,max(observed) largest_observed_group FROM (SELECT p.population,x.{field},count(*) observed,count(DISTINCT x.{size}) sizes,min(x.{size}) stored_size FROM article a JOIN analytics x ON x.id=a.id CROSS JOIN populations p WHERE x.{field}>=0 AND (NOT p.exclude_stubs OR NOT a.stub) GROUP BY 1,2) GROUP BY 1",'Observed group sizes within each Article population; stored size is not assumed current.')
 r.run('major_label_unmatched',"WITH labels AS (SELECT DISTINCT id,stub,unnest(mesh_major_topics) term FROM article WHERE array_length(mesh_major_topics)>0) SELECT p.population,count(*) article_label_pairs,count(*) FILTER(WHERE NOT EXISTS(SELECT 1 FROM am JOIN nodes d ON d.id=am.descriptor WHERE am.article=l.id AND d.name=l.term)) unmatched_article_label_pairs FROM labels l CROSS JOIN populations p WHERE NOT p.exclude_stubs OR NOT l.stub GROUP BY 1",'Exact descriptor-name identity only; unmatched labels never create graph links.')
 create("CREATE OR REPLACE TABLE cited_guideline AS SELECT DISTINCT cc.object article,p.population FROM base.c cc JOIN article a ON a.id=cc.subject CROSS JOIN populations p WHERE (a.guideline OR a.systematic_review) AND (NOT p.exclude_stubs OR NOT a.stub)")
 r.run('B1_population',"SELECT p.population,(SELECT count(*) FROM nodes WHERE label='ClinicalTrial') trials,count(DISTINCT l.trial) trials_with_results,count(DISTINCT l.article) result_articles,count(DISTINCT l.article) FILTER(WHERE g.article IS NOT NULL) result_articles_cited_by_guideline_or_systematic_review,count(DISTINCT l.trial) FILTER(WHERE g.article IS NOT NULL) trials_with_results_cited_by_guideline_or_systematic_review FROM result_links l JOIN article a ON a.id=l.article CROSS JOIN populations p LEFT JOIN cited_guideline g ON g.article=l.article AND g.population=p.population WHERE l.type='VALIDATED_BY' AND (NOT p.exclude_stubs OR NOT a.stub) GROUP BY 1",'All trials; RESULT native links only. Incoming CITES from NLM guideline/Practice Guideline/Systematic Review; Review alone excluded.')
 r.run('background_population',"SELECT p.population,(SELECT count(*) FROM nodes WHERE label='ClinicalTrial') trials,count(*) edge_rows,count(DISTINCT l.trial) trials_with_background,count(DISTINCT l.article) background_articles,count(DISTINCT (l.trial,l.article)) pairs FROM result_links l JOIN article a ON a.id=l.article CROSS JOIN populations p WHERE l.type='CITES_BACKGROUND' AND (NOT p.exclude_stubs OR NOT a.stub) GROUP BY 1",'All trials and explicitly source-designated background publications; no results interpretation.')
 create("CREATE OR REPLACE TABLE annotation_capability AS SELECT m.descriptor,p.population,bool_or(a.gr) gr,bool_or(a.gr AND m.edge_major) gr_major FROM am m JOIN article a ON a.id=m.article CROSS JOIN populations p WHERE NOT p.exclude_stubs OR NOT a.stub GROUP BY 1,2")
 r.run('topic_population',"WITH cap AS (SELECT x.topic,x.mode,p.population,bool_or(coalesce(a.gr,false)) gr,bool_or(coalesce(a.gr_major,false)) gr_major,bool_or(EXISTS(SELECT 1 FROM trial_mesh t WHERE t.object=x.matched_descriptor)) trial FROM topic_expansion x CROSS JOIN populations p LEFT JOIN annotation_capability a ON a.descriptor=x.matched_descriptor AND a.population=p.population GROUP BY 1,2,3) SELECT p.population,m.mode,(SELECT count(*) FROM nodes WHERE label='MedlinePlus') topics,count(*) FILTER(WHERE gr) reaching_guideline_or_review,count(*) FILTER(WHERE gr_major) reaching_major_guideline_or_review,count(*) FILTER(WHERE trial) reaching_condition_trial,count(*) FILTER(WHERE gr AND trial) reaching_both,count(*) FILTER(WHERE gr_major AND trial) reaching_major_both FROM modes m CROSS JOIN populations p CROSS JOIN (SELECT id FROM nodes WHERE label='MedlinePlus') n LEFT JOIN cap c ON c.topic=n.id AND c.mode=m.mode AND c.population=p.population GROUP BY 1,2 ORDER BY 1,2",'All topic nodes/all mapped non-check descriptors; downward none/one/all descendants. Each population excludes stub Article results; trials require condition mesh-list, not source ancestor or intervention mappings.')
 create("CREATE OR REPLACE TABLE citation_shared AS SELECT cc.subject,cc.object,list_has_any(s.source_terms,t.indexed_terms) forward,list_has_any(t.source_terms,s.indexed_terms) reverse FROM base.c cc JOIN profiles s ON s.article=cc.subject JOIN profiles t ON t.article=cc.object WHERE cc.subject<>cc.object AND (list_has_any(s.source_terms,t.indexed_terms) OR list_has_any(t.source_terms,s.indexed_terms))")
 create("CREATE OR REPLACE TABLE citation_reach AS SELECT subject seed,object neighbor FROM citation_shared WHERE forward UNION SELECT object,subject FROM citation_shared WHERE reverse")
 r.run('B3_population',"SELECT p.population,(SELECT count(*) FROM article a WHERE NOT p.exclude_stubs OR NOT a.stub) articles,(SELECT count(*) FROM profiles q JOIN article a ON a.id=q.article WHERE NOT p.exclude_stubs OR NOT a.stub) articles_with_query_terms,count(DISTINCT x.seed) articles_with_citation_neighbor_and_shared_noncheck_query_term,count(*) unique_seed_neighbor_pairs FROM citation_reach x JOIN article a ON a.id=x.seed JOIN article b ON b.id=x.neighbor CROSS JOIN populations p WHERE NOT p.exclude_stubs OR (NOT a.stub AND NOT b.stub) GROUP BY 1,p.exclude_stubs",'Complete Article/citation population; non-check major query terms preferred, otherwise non-check indexing, matching v0.1 traversal definition. Ranking separately requires explicit major on both sides.')
 r.run('B4_population',"SELECT p.population,(SELECT count(*) FROM nodes WHERE label='Author') author_nodes,count(DISTINCT au.object) authors_with_authorship,count(DISTINCT au.object) FILTER(WHERE m.article IS NOT NULL) authors_with_indexed_article,count(DISTINCT au.object) FILTER(WHERE au.match_status='matched') authors_with_matched_authorship FROM authorship au JOIN article a ON a.id=au.subject LEFT JOIN (SELECT DISTINCT article FROM am) m ON m.article=au.subject CROSS JOIN populations p WHERE NOT p.exclude_stubs OR NOT a.stub GROUP BY 1",'All Author nodes; identity caveats retained. Article population explicitly with/without stubs.')
 r.run('journal_population',"SELECT p.population,(SELECT count(*) FROM nodes WHERE label='Journal') journal_nodes,count(DISTINCT e.object) journals_with_articles,count(DISTINCT e.object) FILTER(WHERE a.guideline) journals_with_guidelines,count(DISTINCT a.id) linked_articles,count(DISTINCT a.id) FILTER(WHERE a.guideline) linked_guidelines FROM e JOIN article a ON a.id=e.subject CROSS JOIN populations p WHERE e.type='PUBLISHED_IN' AND (NOT p.exclude_stubs OR NOT a.stub) GROUP BY 1",'Article -> Journal; guideline = exact Guideline/Practice Guideline labels. Journals with no linked guideline remain in denominator.')
 r.run('pmc_integrity',"SELECT (SELECT count(*) FROM nodes WHERE label='PMCRecord') pmc_records,count(*) edges,count(DISTINCT subject) linked_articles,count(DISTINCT object) linked_pmc_records,count(*)-count(DISTINCT subject) extra_edges_over_articles FROM e WHERE type='HAS_PMC_RECORD'",'Identity links to PMC, not a verified download/access/rights claim.')
 create("CREATE OR REPLACE TABLE traversal_articles AS WITH raw AS (SELECT DISTINCT p.population,'results_publications' traversal,l.article FROM result_links l CROSS JOIN populations p WHERE l.type='VALIDATED_BY' UNION SELECT DISTINCT g.population,'results_cited_by_guideline_systematic',l.article FROM result_links l JOIN cited_guideline g ON g.article=l.article WHERE l.type='VALIDATED_BY' UNION SELECT DISTINCT p.population,'background_publications',l.article FROM result_links l CROSS JOIN populations p WHERE l.type='CITES_BACKGROUND' UNION SELECT DISTINCT p.population,'topic_guidelines_reviews',m.article FROM (SELECT DISTINCT matched_descriptor FROM topic_expansion WHERE mode='full') x JOIN am m ON m.descriptor=x.matched_descriptor JOIN article a ON a.id=m.article CROSS JOIN populations p WHERE a.gr UNION SELECT DISTINCT p.population,'citation_shared_neighbors',x.neighbor FROM citation_reach x JOIN article a ON a.id=x.seed CROSS JOIN populations p WHERE NOT p.exclude_stubs OR NOT a.stub UNION SELECT DISTINCT p.population,'author_indexed_articles',article FROM profiles CROSS JOIN populations p WHERE EXISTS(SELECT 1 FROM authorship au WHERE au.subject=profiles.article) UNION SELECT DISTINCT p.population,'journal_guidelines',a.id FROM e JOIN article a ON a.id=e.subject CROSS JOIN populations p WHERE e.type='PUBLISHED_IN' AND a.guideline) SELECT DISTINCT raw.* FROM raw JOIN article a ON a.id=raw.article JOIN populations p ON p.population=raw.population WHERE NOT p.exclude_stubs OR NOT a.stub")
 r.run('pmc_traversal_coverage',"SELECT x.traversal,x.population,count(*) articles,count(*) FILTER(WHERE coalesce(a.pmcid,'')<>'') pmcid,count(*) FILTER(WHERE EXISTS(SELECT 1 FROM e WHERE type='HAS_PMC_RECORD' AND subject=a.id)) pmc_link,count(*) FILTER(WHERE coalesce(a.pmcid,'')<>'' OR EXISTS(SELECT 1 FROM e WHERE type='HAS_PMC_RECORD' AND subject=a.id)) any_pmc_route FROM traversal_articles x JOIN article a ON a.id=x.article GROUP BY 1,2 ORDER BY 1,2",'Distinct Articles in complete traversal families; induced Article populations exclude stub endpoints. PMC route coverage is not independently verified full-text availability/access/rights.')
 examples=[]
 for i,(area,term) in enumerate([('neurology','Epilepsy'),('respiratory','Asthma'),('cardiovascular','Hypertension')],1):
  descriptor=c.execute("SELECT id FROM nodes WHERE label='MeSHConcept' AND name=?",[term]).fetchone()[0]
  specs={
   'results':("SELECT l.trial,l.article result_article,g.id citing_article,l.id publication_edge,cc.id citation_edge,m.edge_id mesh_edge,m.descriptor,g.pub_types citing_types FROM result_links l JOIN am m ON m.article=l.article JOIN base.c cc ON cc.object=l.article JOIN article g ON g.id=cc.subject WHERE l.type='VALIDATED_BY' AND (g.guideline OR g.systematic_review) AND m.descriptor=? AND m.edge_major ORDER BY l.trial,l.article,g.publication_priority,g.id LIMIT 1",[descriptor]),
   'background':("SELECT l.trial,l.article,l.id publication_edge,m.edge_id mesh_edge,m.descriptor,a.name,a.pmcid FROM result_links l JOIN am m ON m.article=l.article JOIN article a ON a.id=l.article WHERE l.type='CITES_BACKGROUND' AND m.descriptor=? AND m.edge_major ORDER BY l.trial,l.article LIMIT 1",[descriptor]),
   'topic':("SELECT x.topic,x.query_descriptor,x.matched_descriptor,x.distance,x.hierarchy_edge,m.article,m.edge_id article_mesh_edge,a.pub_types,t.subject trial,t.id trial_mesh_edge,t.study_aspect,t.mesh_type FROM topic_expansion x JOIN am m ON m.descriptor=x.matched_descriptor JOIN article a ON a.id=m.article JOIN trial_mesh t ON t.object=x.matched_descriptor WHERE x.mode='full' AND x.query_descriptor=? AND a.gr AND m.edge_major ORDER BY a.publication_priority,x.distance,a.id,x.topic,t.subject LIMIT 1",[descriptor]),
   'article':("WITH ss AS (SELECT * FROM seeds WHERE key=?),neighbors AS (SELECT cc.id,cc.subject,cc.object,cc.object neighbor FROM base.c cc JOIN ss ON cc.subject=ss.id UNION ALL SELECT cc.id,cc.subject,cc.object,cc.subject FROM base.c cc JOIN ss ON cc.object=ss.id) SELECT ss.id seed_article,cc.subject citing_article,cc.object cited_article,cc.id citation_edge,m.article neighbor,m.edge_id neighbor_mesh_edge,q.edge_id seed_mesh_edge,m.descriptor,coalesce(ii.in_corpus_citations,0) in_corpus_citations FROM ss JOIN am q ON q.article=ss.id AND q.edge_major AND NOT q.check_tag JOIN neighbors cc ON cc.neighbor<>ss.id JOIN am m ON m.article=cc.neighbor AND m.descriptor=q.descriptor LEFT JOIN incoming ii ON ii.article=m.article ORDER BY in_corpus_citations DESC,m.article,m.descriptor LIMIT 1",['article'+str(i)]),
   'author':("SELECT au.object author,au.subject article,au.id authorship_edge,au.match_status,au.identity_flags,m.descriptor,m.edge_id mesh_edge FROM authorship au JOIN am m ON m.article=au.subject WHERE m.descriptor=? AND au.match_status='matched' ORDER BY au.subject,au.author_order,au.id LIMIT 1",[descriptor]),
   'journal':("SELECT j.id journal,j.name journal_name,a.id guideline,a.pub_types,e.id journal_edge,m.edge_id mesh_edge,m.descriptor FROM e JOIN nodes j ON j.id=e.object AND j.label='Journal' JOIN article a ON a.id=e.subject JOIN am m ON m.article=a.id WHERE e.type='PUBLISHED_IN' AND a.guideline AND m.descriptor=? AND m.edge_major ORDER BY a.id,j.id LIMIT 1",[descriptor])}
  for name,(sql,params) in specs.items():
   rows=r.run(name+'_example_'+str(i),sql,'Purposive '+area+' example; one exact path, not sampled population.',params)
   ex=dict(traversal=name,area=area,rows=rows)
   if rows:
    ids=sorted({v for v in rows[0].values() if isinstance(v,str) and v.startswith(('PMID:','MESH:','clinicaltrials:','lunasai:','nlm:','issn:'))});cur=c.execute('SELECT id,label,name,iri,url,doi,pmcid,stub FROM nodes WHERE id IN (SELECT unnest(?::VARCHAR[]))',[ids]);ex['nodes']=[dict(zip([d[0] for d in cur.description],z)) for z in cur.fetchall()]
    if name=='author':r.run('author_profile_'+str(i),"SELECT m.descriptor,n.name,count(DISTINCT au.subject) articles,arg_min(au.id,au.subject||m.edge_id) authorship_witness,arg_min(m.edge_id,au.subject||m.edge_id) mesh_witness FROM authorship au JOIN am m ON m.article=au.subject JOIN nodes n ON n.id=m.descriptor WHERE au.object=? AND NOT m.check_tag GROUP BY 1,2 ORDER BY articles DESC,m.descriptor LIMIT 10",'Exact profile of a corpus Author ID, not proof of person disambiguation.',[rows[0]['author']])
   examples.append(ex)
 # Whole-field citation leaders are computed separately in both induced Article populations.
 create("CREATE OR REPLACE TABLE incoming_nonstub AS SELECT cc.object article,count(DISTINCT cc.subject) in_corpus_citations FROM base.c cc JOIN article a ON a.id=cc.subject JOIN article b ON b.id=cc.object WHERE NOT a.stub AND NOT b.stub AND cc.subject<>cc.object GROUP BY cc.object")
 for population,tab in [('with_stubs','incoming'),('without_stubs','incoming_nonstub')]:
  for i in range(1,4):
   r.run('whole_field_leaders_'+str(i)+'_'+population,"SELECT a.id,a.name,count(DISTINCT q.query_descriptor) direct_query_matches,coalesce(ii.in_corpus_citations,0) in_corpus_citations FROM query_terms q JOIN am m ON m.descriptor=q.query_descriptor AND m.edge_major JOIN article a ON a.id=m.article LEFT JOIN "+tab+" ii ON ii.article=a.id WHERE q.seed=? AND (?='with_stubs' OR NOT a.stub) GROUP BY a.id,a.name,ii.in_corpus_citations ORDER BY in_corpus_citations DESC,a.id LIMIT 20",'Whole-corpus field, direct major matches, actual in-corpus citations; induced Article population '+population,['article'+str(i),population])
 dump(R/'examples.json',examples);r.save();c.close();print('ANALYSIS COMPLETE',flush=True)
if __name__=='__main__':main()
